add_filter( 'comment_moderation_text', 'perfectpixel_rating_in_review_email', 20, 2 );
add_filter( 'comment_notification_text', 'perfectpixel_rating_in_review_email', 20, 2 );

function perfectpixel_rating_in_review_email( $text, $comment_id ) {
	$comment = get_comment( $comment_id );
	if ( ! $comment || 'product' !== get_post_type( $comment->comment_post_ID ) ) {
		return $text;
	}
	$rating = (int) get_comment_meta( $comment_id, 'rating', true );
	if ( ! $rating ) {
		return $text;
	}
	$stars    = str_repeat( '★', $rating ) . str_repeat( '☆', max( 0, 5 - $rating ) );
	$verified = wc_review_is_from_verified_owner( $comment_id ) ? ' (επιβεβαιωμένος αγοραστής)' : '';
	return sprintf( "Βαθμολογία: %d/5 %s%s\r\n\r\n", $rating, $stars, $verified ) . $text;
}
